{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$comment": "Validation uses standard JSON Schema. Before validating, Thunderbird normalizes platform input in PolicySchemaValidator.sys.mjs: a value delivered as a JSON string is parsed where contentMediaType is application/json, and 0/1 integers become booleans. After validation, strings with format moz-url (any string the WHATWG URL parser accepts) become URL objects, and a list entry that fails validation is dropped and logged rather than discarding the whole policy.",
  "definitions": {
    "url": { "type": "string", "format": "moz-url" },
    "urlOrEmpty": {
      "type": "string",
      "anyOf": [{ "format": "moz-url" }, { "maxLength": 0 }]
    },
    "origin": {
      "type": "string",
      "format": "moz-url",
      "pattern": "^([Ff][Ii][Ll][Ee]://.*|[Hh][Tt][Tt][Pp][Ss]?://[^/]+/?)$"
    }
  },
  "type": "object",
  "properties": {
    "3rdparty": {
      "type": "object",
      "properties": {
        "Extensions": {
          "type": "object",
          "patternProperties": {
            "^.*$": {
              "type": ["object", "array"],
              "contentMediaType": "application/json"
            }
          }
        }
      }
    },

    "AppAutoUpdate": {
      "type": "boolean"
    },

    "AppUpdatePin": {
      "type": "string"
    },

    "AppUpdateURL": { "$ref": "#/definitions/url" },
